const input = $input.first().json;
const body = input.body || input;
const killSwitch = $env.PAUSAR_DIRETOR_COMERCIAL === 'true';
const endpoint = $env.OPENCLAW_INTENT_ENDPOINT;
const tokenConfigured = Boolean($env.OPENCLAW_INTERNAL_TOKEN);
const eventId = String(body.event_id || body.minimized?.event_id || '');
const errors = [];

if (killSwitch) errors.push('kill_switch_ativo');
if (!eventId) errors.push('event_id_ausente');
if (!endpoint) errors.push('openclaw_intent_endpoint_nao_configurado');
if (!tokenConfigured) errors.push('openclaw_internal_token_nao_configurado');

const payloadMinimo = {
  event_id: eventId,
  event_type: String(body.event_type || body.minimized?.event_type || 'desconhecido'),
  channel: String(body.channel || body.minimized?.channel || 'desconhecido'),
  conversation_id: String(body.conversation_id || body.minimized?.conversation_id || ''),
  message_id: String(body.message_id || body.minimized?.message_id || ''),
  occurred_at: String(body.occurred_at || body.minimized?.occurred_at || new Date().toISOString()),
  raw_text_sha256: body.raw_text_sha256 || body.minimized?.raw_text_sha256 || null,
  raw_text_length: Number(body.raw_text_length || body.minimized?.raw_text_length || 0),
  has_attachment: Boolean(body.has_attachment || body.minimized?.has_attachment),
  source_system: 'e-chat',
  mirror_mode: true
};

return [{ json: {
  status_pre_consulta: errors.length ? 'fila_humana' : 'consultar_cerebro',
  route_pre_consulta: errors.length ? 'fila_humana' : 'openclaw_interno',
  errors,
  payload_minimo: payloadMinimo,
  execute_external_message: false,
  sends_external_message: false,
  retry_automatico: false
} }];

const pre = $('Preflight sem dado sensível').first().json;
const response = $input.first().json;
const failed = Boolean(response.error || response.message?.includes?.('ECONN') || response.statusCode >= 400);

if (failed) {
  return [{ json: {
    workflow: 'SST · F2 Consulta ao Cérebro',
    status: 'fila_humana',
    reason: 'openclaw_indisponivel_ou_timeout',
    retry_automatico: false,
    sends_external_message: false,
    execute: false,
    payload_minimo: pre.payload_minimo
  } }];
}

return [{ json: {
  workflow: 'SST · F2 Consulta ao Cérebro',
  status: 'intencao_recebida_modo_espelho',
  next: 'SST · F3 Política',
  retry_automatico: false,
  sends_external_message: false,
  execute: false,
  intent: response.intent || response,
  source_event: pre.payload_minimo
} }];

const pre = $('Preflight sem dado sensível').first().json;
return [{ json: {
  workflow: 'SST · F2 Consulta ao Cérebro',
  status: 'fila_humana',
  reason: pre.errors.join(','),
  retry_automatico: false,
  sends_external_message: false,
  execute: false,
  payload_minimo: pre.payload_minimo
} }];
